  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nenum Role {\n  CLIENT\n  TECHNICIAN\n  ADMIN\n}\n\nenum AppointmentStatus {\n  PENDING\n  ASSIGNED\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\nmodel User {\n  id                String             @id @default(uuid())\n  email             String             @unique\n  password          String\n  firstName         String\n  lastName          String\n  phone             String?\n  role              Role               @default(CLIENT)\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n  technicianProfile TechnicianProfile?\n  appointments      Appointment[]      @relation(\"ClientAppointments\")\n\n  @@map(\"users\")\n}\n\nmodel TechnicianProfile {\n  id            String        @id @default(uuid())\n  userId        String        @unique\n  user          User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  specialties   String[] // Ej: [\"Chillers\", \"VRF\", \"Residencial\"]\n  isActive      Boolean       @default(true)\n  licenseNumber String?       @unique\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n  appointments  Appointment[] @relation(\"TechnicianAppointments\")\n\n  @@map(\"technician_profiles\")\n}\n\nmodel Appointment {\n  id           String             @id @default(uuid())\n  clientId     String\n  client       User               @relation(\"ClientAppointments\", fields: [clientId], references: [id], onDelete: Cascade)\n  technicianId String?\n  technician   TechnicianProfile? @relation(\"TechnicianAppointments\", fields: [technicianId], references: [id], onDelete: SetNull)\n  status       AppointmentStatus  @default(PENDING)\n  scheduledAt  DateTime\n  notes        String?\n  createdAt    DateTime           @default(now())\n  updatedAt    DateTime           @updatedAt\n  equipment    Equipment[]\n  assignments  PartAssignment[]\n\n  @@index([clientId])\n  @@index([technicianId])\n  @@map(\"appointments\")\n}\n\nmodel Equipment {\n  id                 String      @id @default(uuid())\n  appointmentId      String\n  appointment        Appointment @relation(fields: [appointmentId], references: [id], onDelete: Cascade)\n  brand              String // Ej: Carrier, LG, Trane\n  model              String\n  serialNumber       String?\n  btuCapacity        Int? // Capacidad en BTU/h\n  failureDescription String // Motivo del mantenimiento o reporte de falla\n\n  @@map(\"equipments\")\n}\n\nmodel SparePart {\n  id          String           @id @default(uuid())\n  sku         String           @unique // Código único de inventario\n  name        String // Ej: \"Capacitor de marcha 45 Mfd x 440V\"\n  description String?\n  price       Decimal          @db.Decimal(10, 2)\n  stock       Int              @default(0)\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n  assignments PartAssignment[]\n\n  @@map(\"spare_parts\")\n}\n\nmodel PartAssignment {\n  id            String      @id @default(uuid())\n  partId        String\n  sparePart     SparePart   @relation(fields: [partId], references: [id], onDelete: Cascade)\n  appointmentId String\n  appointment   Appointment @relation(fields: [appointmentId], references: [id], onDelete: Cascade)\n  quantity      Int // Cantidad de unidades utilizadas en esa cita\n  assignedAt    DateTime    @default(now())\n\n  @@index([appointmentId])\n  @@index([partId])\n  @@map(\"part_assignments\")\n}\n",
